/// ...and the crimson-world variant, where one exists.
static CRAFTED_BY_CRIMSON: [(u16, u16); 15] = [
    (273, 1645),
    (287, 198),
    (300, 111),
    (556, 2265),
    (3266, 1317),
    (3267, 1318),
    (3268, 1319),
    (4076, 2257),
    (4131, 2256),
    (4745, 1881),
    (5092, 74),
    (5107, 1556),
    (5120, 2254),
    (5322, 1499),
    (5457, 1305),
];

/// ...and the corruption one.
static CRAFTED_BY_CORRUPTION: [(u16, u16); 15] = [
    (273, 1644),
    (287, 197),
    (300, 110),
    (556, 2264),
    (3266, 1314),
    (3267, 1315),
    (3268, 1316),
    (4076, 2258),
    (4131, 2255),
    (4745, 1880),
    (5092, 73),
    (5107, 1542),
    (5120, 2253),
    (5322, 1498),
    (5457, 1304),
];

fn look_up(table: &[(u16, u16)], key: u16) -> Option<u16> {
    table
        .binary_search_by_key(&key, |&(k, _)| k)
        .ok()
        .map(|at| table[at].1)
}

/// The recipe an item would be broken apart by, if any.
///
/// `ShimmerTransforms.GetDecraftingRecipeIndex`: a world's evil decides between two variants
/// where both exist, so the same item decrafts differently in a crimson world.
pub fn decraft_recipe(item: u16, crimson: bool) -> Option<&'static Recipe> {
    let base = look_up(&CRAFTED_BY, item)?;
    let chosen = if crimson {
        look_up(&CRAFTED_BY_CRIMSON, item).unwrap_or(base)
    } else {
        look_up(&CRAFTED_BY_CORRUPTION, item).unwrap_or(base)
    };
    RECIPES.get(chosen as usize)
}

impl Recipe {
    /// What this recipe wanted.
    pub fn ingredients(&self) -> &'static [Ingredient] {
        let from = self.first as usize;
        &INGREDIENTS[from..from + self.count as usize]
    }
}

/// Whether a recipe is one the world has not earned yet.
///
/// Two gates: some recipes cannot be decrafted until Skeletron is down, others until the Golem
/// is. The game keeps these as recipe sets; both are small and are passed in rather than tabled,
/// since the caller already knows the world's progress.
pub fn decraft_locked(_recipe: &Recipe, _downed_skeletron: bool, _downed_golem: bool) -> bool {
    // `RecipeSets.PostSkeletron` and `PostGolem` are empty in 1.4.5.7 — the gates exist and
    // nothing is behind them. Kept as a named function so a later version that fills them in
    // needs a table rather than a new concept.
    false
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The lookups are sorted, or the binary searches silently miss.
    #[test]
    fn the_lookups_are_sorted() {
        for (name, table) in [
            ("CRAFTED_BY", &CRAFTED_BY[..]),
            ("CRAFTED_BY_CRIMSON", &CRAFTED_BY_CRIMSON[..]),
            ("CRAFTED_BY_CORRUPTION", &CRAFTED_BY_CORRUPTION[..]),
        ] {
            assert!(
                table.windows(2).all(|w| w[0].0 < w[1].0),
                "{name} must be strictly ascending"
            );
        }
    }

    /// Every recipe's ingredient span lies inside the packed array and holds real items.
    #[test]
    fn every_recipe_points_at_real_ingredients() {
        for recipe in RECIPES {
            let end = recipe.first as usize + recipe.count as usize;
            assert!(
                end <= INGREDIENTS.len(),
                "item {} runs past the ingredient table",
                recipe.result
            );
            assert!(
                recipe.count > 0,
                "item {} has no ingredients",
                recipe.result
            );
            assert!(recipe.makes > 0, "item {} makes nothing", recipe.result);
            for &(item, stack) in recipe.ingredients() {
                assert!(item > 0, "recipe for {} wants item zero", recipe.result);
                assert!(
                    stack > 0,
                    "recipe for {} wants none of {item}",
                    recipe.result
                );
            }
        }
    }

    /// Every index in the lookups names a recipe that exists.
    #[test]
    fn every_lookup_names_a_recipe() {
        for table in [
            &CRAFTED_BY[..],
            &CRAFTED_BY_CRIMSON[..],
            &CRAFTED_BY_CORRUPTION[..],
        ] {
            for &(item, at) in table {
                assert!(
                    (at as usize) < RECIPES.len(),
                    "item {item} names recipe {at}, past the end"
                );
            }
        }
    }

    /// A well-known one, end to end.
    #[test]
    fn a_torch_decrafts_into_what_it_was_made_of() {
        let torch = decraft_recipe(8, false).expect("a torch is crafted");
        assert_eq!(torch.result, 8);
        assert_eq!(torch.makes, 3, "three torches at a time");
        let wants: Vec<u16> = torch.ingredients().iter().map(|&(i, _)| i).collect();
        assert!(wants.contains(&23), "a torch wants gel");
    }

    /// Something that is not crafted decrafts into nothing.
    ///
    /// Note that a great deal *is* crafted, including things that feel primitive — an Iron
    /// Pickaxe is ten bars and three wood. So this checks the shape of the answer rather than
    /// guessing at which items are raw.
    #[test]
    fn raw_materials_do_not_decraft() {
        assert!(decraft_recipe(0, false).is_none(), "nothing at all");
        let uncraftable = (1u16..2000)
            .filter(|&i| decraft_recipe(i, false).is_none())
            .count();
        assert!(
            uncraftable > 100,
            "only {uncraftable} of the first two thousand items are uncrafted, which is too few"
        );
    }

    /// The two evils can disagree about what an item is made of.
    #[test]
    fn the_evils_can_differ() {
        let differing = (0u16..u16::MAX).filter(|&i| {
            match (decraft_recipe(i, false), decraft_recipe(i, true)) {
                (Some(a), Some(b)) => a != b,
                _ => false,
            }
        });
        assert!(
            differing.take(1).count() > 0 || CRAFTED_BY_CRIMSON.is_empty(),
            "if any recipe is evil-specific, some item should decraft differently"
        );
    }

    /// D1: a fake chest still decrafts into what it was made of.
    ///
    /// `Recipe.cs` 6524-6532: the `for (int i = 3665; i <= 3704; i++)` texture-copy loop. Item
    /// 3665 (`Fake_Chest`) copies the Regular Chest's texture, so it wants Regular Chest (48) and
    /// ten Wire (530): `ItemID.Sets.TextureCopyLoad[3665] == 48` (`Terraria.ID/ItemID.cs` 1096).
    #[test]
    fn a_fake_chest_decrafts_into_its_wire_and_copied_chest() {
        let fake_chest = decraft_recipe(3665, false).expect("a fake chest is crafted");
        assert_eq!(fake_chest.makes, 1);
        let wants: Vec<(u16, u16)> = fake_chest.ingredients().to_vec();
        assert_eq!(wants, vec![(48, 1), (530, 10)]);
    }

    /// D1: a critter statue decrafts into its stone and its critter.
    ///
    /// `Recipe.cs` 9630 (`AddCritterStatueRecipe(444, 261)`, helper at 16702-16718): the Fish
    /// Statue (444) wants fifty Stone Block (3) and five Goldfish (261).
    #[test]
    fn a_critter_statue_decrafts_into_stone_and_its_critter() {
        let statue = decraft_recipe(444, false).expect("a fish statue is crafted");
        assert_eq!(statue.makes, 1);
        let wants: Vec<(u16, u16)> = statue.ingredients().to_vec();
        assert_eq!(wants, vec![(3, 50), (261, 5)]);
    }

    /// D1: `AddCritterStatueRecipe`'s `RecipeGroup` branch resolves to the group's first member.
    ///
    /// `Recipe.cs` 9632 (`AddCritterStatueRecipe(3651, 0, RecipeGroups.Squirrels)`): the Squirrel
    /// statue wants five of item 2018, the Squirrel: `RecipeGroups.Squirrels`'s first member
    /// (`Recipe.cs` 501, `SetupRecipeGroups`), not the literal `0` the call passes.
    #[test]
    fn a_group_based_critter_statue_resolves_the_groups_first_member() {
        let statue = decraft_recipe(3651, false).expect("a squirrel statue is crafted");
        let wants: Vec<(u16, u16)> = statue.ingredients().to_vec();
        assert_eq!(wants, vec![(3, 50), (2018, 5)]);
    }

    /// D1: a gemspark wall decrafts back into the ordinary one-block-to-four-walls ratio.
    ///
    /// `Recipe.cs` 3188-3195: the first of seven `num2/num3/num4` gemspark-wall blocks. Item 2679
    /// (`AmethystGemsparkWall`, `num3`) is four walls made from one Amethyst Gemspark Block (1970,
    /// `num2`).
    #[test]
    fn a_gemspark_wall_makes_four_from_one_block() {
        let wall = decraft_recipe(2679, false).expect("a gemspark wall is crafted");
        assert_eq!(
            wall.makes, 4,
            "the loop's createItem.stack = 4, the usual block-to-wall ratio"
        );
        let wants: Vec<(u16, u16)> = wall.ingredients().to_vec();
        assert_eq!(wants, vec![(1970, 1)]);
    }

    /// D1: `StrungCounterweight`'s six-iteration loop was a real bug in the pre-D1 table, not just
    /// a gap: `Recipe.cs` 9456-9463 sets a literal `createItem` (5547) but a loop-variable second
    /// ingredient, so the generic parse used to keep a real but truncated recipe: White String
    /// (3306) alone, with the second ingredient silently dropped. The last iteration (l = 3314)
    /// wants White String and item 3314 both.
    #[test]
    fn a_strung_counterweight_wants_both_strings_not_just_one() {
        let counterweight = decraft_recipe(5547, false).expect("a counterweight is crafted");
        let wants: Vec<(u16, u16)> = counterweight.ingredients().to_vec();
        assert_eq!(
            wants,
            vec![(3306, 1), (3314, 1)],
            "the pre-D1 table only recovered the first ingredient here"
        );
    }

    /// D1: `AddStandardFurnitureSetRecipes` called twice from `AddPineFurniture` (`Recipe.cs`
    /// 16520-16524) with the same nineteen result items but two different primary materials (1872,
    /// then 5930): the second call's recipes must win, the same last-recipe-wins rule as anywhere
    /// else in `SetupRecipes`.
    #[test]
    fn pine_furnitures_second_call_wins_over_its_first() {
        let bathtub = decraft_recipe(5840, false).expect("a pine bathtub is crafted");
        let wants: Vec<(u16, u16)> = bathtub.ingredients().to_vec();
        assert_eq!(
            wants,
            vec![(5930, 14)],
            "the second AddStandardFurnitureSetRecipes(5930, ...) call must win over the first \
             AddStandardFurnitureSetRecipes(1872, ...) one"
        );
    }

    /// D1 in one number: a future extractor regression that silently stops seeing the loop-built
    /// families should be loud, not a quiet shrink nobody notices.
    #[test]
    fn the_decraft_table_includes_the_loop_built_families() {
        assert_eq!(
            CRAFTED_BY.len(),
            3083,
            "expected 2536 pre-D1 craftable items plus 547 loop-built ones"
        );
    }
}
